from fractions import Fraction

class Solution:
    def isRationalEqual(self, s: str, t: str) -> bool:
        return self.value(s) == self.value(t)

    def value(self, text: str) -> Fraction:
        if '.' not in text:
            return Fraction(int(text), 1)

        integer, decimal = text.split('.')
        if '(' not in decimal:
            numerator = int((integer or '0') + decimal) if decimal else int(integer or '0')
            return Fraction(numerator, 10 ** len(decimal))

        non_repeat, repeat = decimal.split('(')
        repeat = repeat[:-1]
        base = Fraction(int(integer or '0'), 1)
        if non_repeat:
            base += Fraction(int(non_repeat), 10 ** len(non_repeat))
        repeated = Fraction(int(repeat), (10 ** len(repeat) - 1) * (10 ** len(non_repeat)))
        return base + repeated
